7	/**
8	 * Derives an owner's canonical region ("locality"). The postcode is preferred:
9	 * a 4-digit postcode is matched against each region's inclusive range first, and
10	 * only when the postcode is absent or in no known range does derivation fall back
11	 * to a fixed city-to-region table. Kept as a plain utility (rather than a mapper
12	 * method) so MapStruct does not treat it as an implicit {@code String -> String}
13	 * mapping.
14	 */
15	public final class Localities {
16	
17	    /** City -> canonical region. Anything not listed derives {@link #UNKNOWN}. */
18	    private static final Map<String, String> CITY_REGION = Map.of(
19	        "Sydney", "NSW",
20	        "Melbourne", "VIC",
21	        "Brisbane", "QLD");
22	
23	    /** Region -> inclusive 4-digit postcode range {low, high}. */
24	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
25	        "NSW", new int[] {2000, 2099},
26	        "VIC", new int[] {3000, 3099},
27	        "QLD", new int[] {4000, 4099});
28	
29	    /** Region -> IANA timezone name. Anything not listed derives a {@code null} timezone. */
30	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
31	        "NSW", "Australia/Sydney",
32	        "VIC", "Australia/Melbourne",
33	        "QLD", "Australia/Brisbane");
34	
35	    /** Region returned for a city that is absent from {@link #CITY_REGION}. */
36	    public static final String UNKNOWN = "UNKNOWN";
37	
38	    private Localities() {
39	    }
40	
41	    /**
42	     * Returns the canonical region for {@code city} from the fixed table
43	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}),
44	     * or {@code "UNKNOWN"} when the city is {@code null} or not in the table.
45	     *
46	     * @param city the owner's city
47	     * @return the canonical region string, or {@code "UNKNOWN"} when unknown
48	     */
49	    public static String forCity(String city) {
50	        if (city == null) {
51	            return UNKNOWN;
52	        }
53	        return CITY_REGION.getOrDefault(city, UNKNOWN);
54	    }
55	
56	    /**
57	     * Returns the canonical region, preferring the {@code postcode}: it is matched
58	     * against each region's inclusive postcode range first (NSW 2000-2099,
59	     * VIC 3000-3099, QLD 4000-4099). Only when the postcode is {@code null},
60	     * non-numeric, or in no known range does derivation fall back to the
61	     * {@link #forCity(String) city-to-region table}. This returns the same region
62	     * for known cities but disambiguates cities that share a name.
63	     *
64	     * @param city the owner's city
65	     * @param postcode the owner's postcode, may be {@code null}
66	     * @return the canonical region string, or {@code "UNKNOWN"} when unknown
67	     */
68	    public static String forCityAndPostcode(String city, String postcode) {
69	        String region = forPostcode(postcode);
70	        if (region != null) {
71	            return region;
72	        }
73	        return forCity(city);
74	    }
75	
76	    /**
77	     * Returns the owner's canonical region ("locality"), sourced from the region-and-hash
78	     * {@code customerCode} identity: the {@code <REGION>} prefix of the {@code customerCode}
79	     * (the part before the first {@code '-'}) when one has been assigned, so the locality is
80	     * exactly the region the identity was built on. When the owner has no customer code yet
81	     * (for example seed data created before the identity was assigned) derivation falls back to
82	     * {@link #forCityAndPostcode(String, String)} over the owner's city and postcode, which
83	     * computes the same region the identity would have used.
84	     *
85	     * @param owner the owner whose locality is required
86	     * @return the canonical region string, or {@code "UNKNOWN"} when unknown
87	     */
88	    public static String forOwner(Owner owner) {
89	        String customerCode = owner.getCustomerCode();
90	        if (customerCode != null) {
91	            int dash = customerCode.indexOf('-');
92	            if (dash > 0) {
93	                return customerCode.substring(0, dash);
94	            }
95	        }
96	        return forCityAndPostcode(owner.getCity(), owner.getPostcode());
97	    }
98	
99	    /**
100	     * Returns the IANA timezone name for {@code region} from the fixed region-to-timezone
101	     * table ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
102	     * {@code QLD -> Australia/Brisbane}), or {@code null} when the region is {@code null}
103	     * or not in the table (for example {@code "UNKNOWN"}).
104	     *
105	     * @param region the canonical region string
106	     * @return the IANA timezone name, or {@code null} when unknown
107	     */
108	    public static String timezoneForRegion(String region) {
109	        if (region == null) {
110	            return null;
111	        }
112	        return REGION_TIMEZONE.get(region);
113	    }
114	
115	    /**
116	     * Returns the owner's IANA timezone name, derived from the owner's locality/region
117	     * ({@link #forOwner(Owner)}) via the fixed region-to-timezone table, or {@code null}
118	     * when the region is not in the table.
119	     *
120	     * @param owner the owner whose timezone is required
121	     * @return the IANA timezone name, or {@code null} when unknown
122	     */
123	    public static String timezoneForOwner(Owner owner) {
124	        return timezoneForRegion(forOwner(owner));
125	    }
126	
127	    /**
128	     * Returns the region whose inclusive postcode range contains {@code postcode},
129	     * or {@code null} when the postcode is {@code null}, non-numeric, or in no
130	     * known range.
131	     */
132	    private static String forPostcode(String postcode) {
133	        if (postcode == null) {
134	            return null;
135	        }
