16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "postcode")
48	    private String postcode;
49	
50	    @Column(name = "telephone")
51	    @NotEmpty
52	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 format (a '+' followed by 8 to 15 digits)")
53	    private String telephone;
54	
55	    @Column(name = "email")
56	    @Email
57	    private String email;
58	
59	    @Column(name = "registration_date")
60	    private LocalDate registrationDate;
61	
62	    @Column(name = "birth_date")
63	    private LocalDate birthDate;
64	
65	    @Column(name = "customer_code")
66	    private String customerCode;
67	
68	    @Column(name = "household_id")
69	    private String householdId;
70	
71	    @Column(name = "namesake_count")
72	    private Integer namesakeCount;
73	
74	    @Column(name = "bulk_signup_warning")
75	    private Boolean bulkSignupWarning;
76	
77	    @Column(name = "household_size")
78	    private Integer householdSize;
79	
80	    @Column(name = "possible_duplicate")
81	    private Boolean possibleDuplicate;
82	
83	    @Column(name = "possible_duplicate_of")
84	    private Integer possibleDuplicateOf;
85	
86	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
87	    private Set<Pet> pets;
88	
89	    public String getAddress() {
90	        return this.address;
91	    }
92	
93	    public void setAddress(String address) {
94	        this.address = address;
95	    }
96	
97	    public String getCity() {
98	        return this.city;
99	    }
100	
101	    public void setCity(String city) {
102	        this.city = city;
103	    }
104	
105	    public String getPostcode() {
106	        return this.postcode;
107	    }
108	
109	    public void setPostcode(String postcode) {
110	        this.postcode = postcode;
111	    }
112	
113	    public String getTelephone() {
114	        return this.telephone;
115	    }
116	
117	    public void setTelephone(String telephone) {
118	        this.telephone = telephone;
119	    }
120	
121	    /**
122	     * The known E.164 country calling codes used to split the stored telephone into its country
123	     * code and national digits when formatting {@link #getTelephoneDisplay()}. Ordered
124	     * longest-first so the most specific code wins; this mirrors the codes the application
125	     * recognises elsewhere (Australia {@code '+61'} and the NANP {@code '+1'}).
126	     */
127	    private static final List<String> KNOWN_COUNTRY_CODES = List.of("61", "1");
128	
129	    /**
130	     * The stored E.164 {@link #telephone} formatted for humans: the country code, a space, then the
131	     * national digits grouped in threes from the left and separated by spaces. So the stored
132	     * {@code '+61412345678'} is displayed as {@code '+61 412 345 678'}. The raw {@link #telephone}
133	     * itself is left in E.164 form. A {@code null} telephone yields {@code null}, and a value not in
134	     * E.164 form (no leading {@code '+'}) is returned unchanged.
135	     *
136	     * @return the human-formatted telephone, or {@code null} when no telephone is stored
137	     */
138	    @Transient
139	    public String getTelephoneDisplay() {
140	        if (this.telephone == null || !this.telephone.startsWith("+")) {
141	            return this.telephone;
142	        }
143	        String allDigits = this.telephone.substring(1);
144	        if (allDigits.isEmpty()) {
145	            return this.telephone;
146	        }
147	        String countryCode = null;
148	        for (String code : KNOWN_COUNTRY_CODES) {
149	            if (allDigits.startsWith(code)) {
150	                countryCode = code;
151	                break;
152	            }
153	        }
154	        if (countryCode == null) {
155	            countryCode = allDigits.substring(0, 1);
156	        }
157	        String national = allDigits.substring(countryCode.length());
158	        StringBuilder display = new StringBuilder("+").append(countryCode);
159	        for (int i = 0; i < national.length(); i += 3) {
160	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
161	        }
162	        return display.toString();
163	    }
164	
165	    public String getEmail() {
166	        return this.email;
167	    }
168	
169	    public void setEmail(String email) {
170	        this.email = email;
171	    }
172	
173	    public LocalDate getRegistrationDate() {
174	        return this.registrationDate;
175	    }
176	
177	    public void setRegistrationDate(LocalDate registrationDate) {
178	        this.registrationDate = registrationDate;
179	    }
180	
181	    public LocalDate getBirthDate() {
182	        return this.birthDate;
183	    }
184	
185	    public void setBirthDate(LocalDate birthDate) {
186	        this.birthDate = birthDate;
