192	    /**
193	     * Rolls a registration date forward to a business day. When {@code date} falls on a Saturday or
194	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
195	     * to the effective registration date (whether supplied in the request or defaulted to the server
196	     * date) so that every stored {@code registrationDate}, and any value derived from it, lands on a
197	     * business day.
198	     *
199	     * @param date the effective registration date
200	     * @return the same date if it is a weekday, otherwise the following Monday
201	     */
202	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
203	        return switch (date.getDayOfWeek()) {
204	            case SATURDAY -> date.plusDays(2);
205	            case SUNDAY -> date.plusDays(1);
206	            default -> date;
207	        };
208	    }
209	
210	    /**
211	     * Counts the owners that already exist (before the current create) whose first and last names
212	     * both match the supplied names, compared case-insensitively. The returned value is captured on
213	     * the new owner at creation time and does not change as further owners are added later.
214	     *
215	     * @param firstName the new owner's first name
216	     * @param lastName  the new owner's last name
217	     * @return the number of pre-existing namesake owners
218	     */
219	    private int namesakeCount(String firstName, String lastName) {
220	        return (int) this.clinicService.findAllOwners().stream()
221	            .filter(existing -> existing.getFirstName() != null
222	                && existing.getFirstName().equalsIgnoreCase(firstName)
223	                && existing.getLastName() != null
224	                && existing.getLastName().equalsIgnoreCase(lastName))
225	            .count();
226	    }
227	
228	    /**
229	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where
230	     * {@code REGION} is the canonical region derived from the owner's postcode (falling back to
231	     * the city when the postcode is absent or in no known range, see
232	     * {@link org.springframework.samples.petclinic.mapper.Localities#forCityAndPostcode}), and
233	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the
234	     * normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). Unlike
235	     * the previous city-prefixed scheme it carries no per-city sequence number, so the identity is
236	     * a pure function of the owner's region, telephone and last name.
237	     *
238	     * @param city                the owner's city
239	     * @param postcode            the owner's postcode, may be {@code null}
240	     * @param normalizedTelephone the owner's telephone, already normalized to E.164
241	     * @param lastName            the owner's last name
242	     * @return the assigned customer code
243	     */
244	    private String customerCode(String city, String postcode, String normalizedTelephone, String lastName) {
245	        String region = org.springframework.samples.petclinic.mapper.Localities
246	            .forCityAndPostcode(city, postcode);
247	        String hash8 = sha256UpperHex((normalizedTelephone == null ? "" : normalizedTelephone)
248	            + (lastName == null ? "" : lastName), 8);
249	        return region + "-" + hash8;
250	    }
251	
252	    /**
253	     * Ensures the computed {@code customerCode} is unique across existing owners. When {@code baseCode}
254	     * does not collide with any existing owner's {@code customerCode} it is returned unchanged.
255	     * Otherwise {@code '-<n>'} is appended, using the smallest {@code n} of 2 or more that yields a
256	     * value not already in use, and that de-duplicated code is returned.
257	     *
258	     * @param baseCode the freshly computed customer code
259	     * @return {@code baseCode} if unused, otherwise {@code baseCode + "-" + n} for the smallest free n
260	     */
261	    private String deduplicateCustomerCode(String baseCode) {
262	        java.util.Set<String> inUse = this.clinicService.findAllOwners().stream()
263	            .map(org.springframework.samples.petclinic.model.Owner::getCustomerCode)
264	            .filter(java.util.Objects::nonNull)
265	            .collect(java.util.stream.Collectors.toSet());
266	        if (!inUse.contains(baseCode)) {
267	            return baseCode;
268	        }
269	        int n = 2;
270	        while (inUse.contains(baseCode + "-" + n)) {
271	            n++;
272	        }
273	        return baseCode + "-" + n;
274	    }
275	
276	    /**
277	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
278	     * UTF-8 bytes of {@code value}.
279	     *
280	     * @param value  the source value to hash
281	     * @param length the number of leading hex characters to return
282	     * @return the leading upper-case hex characters of the digest
283	     */
284	    private String sha256UpperHex(String value, int length) {
285	        try {
286	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
287	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
288	            StringBuilder sb = new StringBuilder(digest.length * 2);
289	            for (byte b : digest) {
290	                sb.append(String.format("%02x", b));
291	            }
292	            return sb.substring(0, length).toUpperCase(java.util.Locale.ROOT);
293	        }
294	        catch (java.security.NoSuchAlgorithmException e) {
295	            throw new IllegalStateException("SHA-256 not available", e);
296	        }
297	    }
298	
299	    /**
300	     * Normalizes a street address applied whenever an owner is created: leading and trailing
301	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
302	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
303	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
304	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
305	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
306	     * {@code '12 MAIN STREET'}.
307	     *
308	     * @param address the raw address as submitted, or {@code null} when absent
309	     * @return the normalized address, or the empty string when the value is blank
310	     */
311	    private String normalizeAddress(String address) {
312	        String collapsed = (address == null ? "" : address)
313	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
314	        if (collapsed.isEmpty()) {
315	            return "";
316	        }
317	        String[] tokens = collapsed.split(" ");
318	        for (int i = 0; i < tokens.length; i++) {
319	            switch (tokens[i]) {
320	                case "ST" -> tokens[i] = "STREET";
321	                case "RD" -> tokens[i] = "ROAD";
322	                case "AVE" -> tokens[i] = "AVENUE";
323	                default -> { }
324	            }
325	        }
326	        return String.join(" ", tokens);
327	    }
328	
329	    /**
330	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
331	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
332	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
333	     * empty string.
334	     *
335	     * @param value the raw value (last name or address) as submitted
336	     * @return the normalized comparison key
337	     */
338	    private String normalizeForHousehold(String value) {
339	        if (value == null) {
340	            return "";
341	        }
342	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
343	    }
344	
345	    /**
346	     * Derives the stable shared household identifier for a household, keyed on the normalized last
347	     * name and address. Because it is a pure function of those normalized keys, every owner in the
348	     * same household deterministically computes the same value. The identifier is the first 12
349	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
350	     * (the separator prevents distinct name/address pairs from colliding).
351	     *
352	     * @param lastNameKey the normalized last-name comparison key
353	     * @param addressKey  the normalized address comparison key
354	     * @return the stable household identifier
355	     */
356	    private String householdId(String lastNameKey, String postcode) {
357	        String seed = lastNameKey + "|" + (postcode == null ? "" : postcode);
358	        try {
359	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
360	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
361	            StringBuilder sb = new StringBuilder(digest.length * 2);
362	            for (byte b : digest) {
363	                sb.append(String.format("%02x", b));
364	            }
365	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
366	        }
367	        catch (java.security.NoSuchAlgorithmException e) {
368	            throw new IllegalStateException("SHA-256 not available", e);
369	        }
370	    }
371	
372	    /**
373	     * The exact number of national (subscriber) digits required for a given country calling code,
374	     * i.e. the digits that follow the country code in an E.164 number. A country code that is not
375	     * listed here has no fixed-length requirement beyond the general 8-to-15-digit E.164 bound.
376	     * Australia ({@code '+61'}) requires 9 national digits and the NANP ({@code '+1'}) requires 10.
377	     */
378	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
379	        java.util.Map.of("61", 9, "1", 10);
380	
381	    /**
382	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
383	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
384	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
385	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
386	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
387	     * is stored as {@code '+61412345678'}.
388	     *
389	     * <p>In addition, when the number's country code has a fixed national-number length (see
390	     * {@link #NATIONAL_NUMBER_LENGTHS}), the national digits that follow the country code must
391	     * match that length exactly: {@code '+61'} requires 9 national digits and {@code '+1'}
392	     * requires 10. So {@code '+61 123'} is rejected because its 3 national digits are not 9.
393	     *
394	     * @param telephone the raw telephone number as submitted
395	     * @return the normalized E.164 telephone number
396	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
397	     *         number (8 to 15 digits after the '+'), or if its national-number length is wrong
398	     *         for its country code
399	     */
400	    private String normalizeTelephone(String telephone) {
401	        String raw = telephone == null ? "" : telephone.trim();
402	        String digits = raw.replaceAll("\\D", "");
403	        String e164;
404	        if (raw.startsWith("+")) {
405	            e164 = "+" + digits;
406	        } else {
407	            if (digits.startsWith("0")) {
408	                digits = digits.substring(1);
409	            }
410	            e164 = "+61" + digits;
411	        }
412	        int digitCount = e164.length() - 1;
413	        if (digitCount < 8 || digitCount > 15) {
414	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
415	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
416	        }
417	        validateNationalNumberLength(e164);
418	        return e164;
419	    }
420	
421	    /**
422	     * Validates that an E.164 number's national-number length is correct for its country code.
423	     * The country code is matched by longest known prefix (so {@code '+61'} is preferred over
424	     * {@code '+1'} would-be matches); when the code has a fixed national-number length the digits
425	     * following it must match exactly. Country codes without a fixed length are left unchecked.
426	     *
427	     * @param e164 the normalized E.164 number (a {@code '+'} followed by digits)
428	     * @throws ResponseStatusException with a 400 status if the national-number length is wrong
429	     *         for the country code
430	     */
431	    private void validateNationalNumberLength(String e164) {
432	        String allDigits = e164.substring(1);
433	        String bestCode = null;
434	        for (String code : NATIONAL_NUMBER_LENGTHS.keySet()) {
435	            if (allDigits.startsWith(code)
436	                    && (bestCode == null || code.length() > bestCode.length())) {
437	                bestCode = code;
438	            }
439	        }
440	        if (bestCode == null) {
441	            return;
442	        }
443	        int nationalLength = allDigits.length() - bestCode.length();
444	        int required = NATIONAL_NUMBER_LENGTHS.get(bestCode);
445	        if (nationalLength != required) {
446	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
447	                "Telephone for country code '+" + bestCode + "' must have " + required
448	                    + " national digits");
449	        }
450	    }
451	
452	    /**
453	     * The inclusive 4-digit postcode range permitted for each canonical region, keyed by the
454	     * region derived from the owner's city ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
455	     * {@code Brisbane -> QLD}): NSW {@code 2000-2099}, VIC {@code 3000-3099}, QLD
456	     * {@code 4000-4099}. A city whose region is not listed here accepts any 4-digit postcode.
457	     */
458	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
459	        "NSW", new int[] {2000, 2099},
460	        "VIC", new int[] {3000, 3099},
461	        "QLD", new int[] {4000, 4099});
462	
463	    /**
464	     * Validates an owner's optional postcode against their city's region. The postcode is only
465	     * checked when present (a {@code null} postcode is accepted, keeping the request contract
466	     * backward-compatible). Its four-digit shape is already enforced by Bean Validation on the
467	     * request DTO. When the city maps to a known region (see {@link #REGION_POSTCODE_RANGES}) the
468	     * postcode must fall within that region's inclusive range; a city with no known region accepts
469	     * any 4-digit postcode.
470	     *
471	     * @param postcode the owner's postcode as submitted, or {@code null} when absent
472	     * @param city     the owner's city, used to derive the region whose range applies
473	     * @throws ResponseStatusException with a 400 status when a supplied postcode is out of range
474	     *         for the city's region
475	     */
476	    private void validatePostcode(String postcode, String city) {
477	        if (postcode == null) {
478	            return;
479	        }
480	        String region = org.springframework.samples.petclinic.mapper.Localities.forCity(city);
481	        int[] range = REGION_POSTCODE_RANGES.get(region);
482	        if (range == null) {
483	            return;
484	        }
485	        int value = Integer.parseInt(postcode);
486	        if (value < range[0] || value > range[1]) {
487	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
488	                "Postcode " + postcode + " is not valid for region " + region);
489	        }
490	    }
491	
492	    /**
493	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
494	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
495	     * (absent) or already valid.
496	     *
497	     * @param email the email address as submitted, or {@code null} when absent
498	     * @return the lower-cased email, or {@code null} when absent
499	     */
500	    private String normalizeEmail(String email) {
501	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
502	    }
503	
504	    /**
505	     * The set of disposable email domains an owner's email may not use. These throwaway-mailbox
506	     * providers are rejected because they cannot be relied on for durable contact.
507	     */
508	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
509	        "mailinator.com", "tempmail.com", "guerrillamail.com");
510	
511	    /**
512	     * Rejects an owner whose email domain is on the disposable-domain blocklist. The email has
513	     * already been normalized to lower-case, so the domain (the part after the last {@code '@'}) is
514	     * compared case-insensitively against {@link #DISPOSABLE_EMAIL_DOMAINS}. A {@code null} email
515	     * (absent) is accepted, keeping the field optional.
516	     *
517	     * @param email the normalized email address, or {@code null} when absent
518	     * @throws ResponseStatusException with a 400 status when the email domain is blocklisted
519	     */
520	    private void validateEmailDomain(String email) {
521	        if (email == null) {
522	            return;
523	        }
524	        int at = email.lastIndexOf('@');
525	        if (at < 0) {
526	            return;
527	        }
528	        String domain = email.substring(at + 1);
529	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
530	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
531	                "Email domain " + domain + " is not allowed");
532	        }
533	    }
534	
535	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
536	    @Override
537	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
538	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
539	        if (currentOwner == null) {
540	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
541	        }
542	        currentOwner.setAddress(ownerFieldsDto.getAddress());
543	        currentOwner.setCity(ownerFieldsDto.getCity());
544	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
545	        currentOwner.setLastName(ownerFieldsDto.getLastName());
546	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
547	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
548	        this.clinicService.saveOwner(currentOwner);
